<?php if ($invoices === []): ?><div class="patient-empty-state"><i class="bi bi-receipt" aria-hidden="true"></i><strong>No invoices found</strong><span>Invoices linked to your patient account will appear here.</span></div><?php else: ?><div class="patient-invoices-grid"><?php foreach ($invoices as $invoice): ?><article class="patient-invoice-card"><div class="patient-invoice-card-header"><div><span class="patient-eyebrow">Invoice</span><h3 title="<?= esc($invoice['invoice_number'], 'attr') ?>"><?= esc($invoice['invoice_number']) ?></h3></div><span class="badge patient-status-badge patient-status-<?= esc($invoice['payment_status']) ?>"><?= esc($invoice['payment_status_label']) ?></span></div><dl class="patient-invoice-card-details"><div><dt>Date</dt><dd><?= esc($invoice['invoice_date_display']) ?></dd></div><div><dt>Order</dt><dd title="<?= esc($invoice['order_number'] ?? '', 'attr') ?>"><?= esc($invoice['order_number'] ?: 'Unavailable') ?></dd></div><div><dt>Prescription</dt><dd title="<?= esc($invoice['prescription_number'] ?? '', 'attr') ?>"><?= esc($invoice['prescription_number'] ?: 'Unavailable') ?></dd></div><div><dt>Total</dt><dd><?= esc(($invoice['currency'] ?? 'INR') . ' ' . number_format((float) ($invoice['total'] ?? 0), 2)) ?></dd></div></dl><p class="patient-invoice-card-provider"><strong><?= esc($invoice['payment_provider'] ?: 'Provider not recorded') ?></strong><span title="<?= esc($invoice['payment_reference'] ?? '', 'attr') ?>"><?= esc($invoice['payment_reference'] ?: 'No payment reference') ?></span></p><p class="patient-card-meta"><i class="fa-solid fa-circle-exclamation mr-1" aria-hidden="true"></i>Updated <?= esc($invoice['updated_at'] ?? '—') ?></p><div class="patient-invoice-card-actions"><div class="dropdown"><button class="btn btn-sm btn-primary dropdown-toggle" type="button" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false">More Actions</button><div class="dropdown-menu dropdown-menu-right"><button class="dropdown-item patient-invoice-view" type="button" data-id="<?= (int) $invoice['id'] ?>" data-toggle="modal" data-target="#patient-invoice-detail-modal">View invoice</button><button class="dropdown-item patient-invoice-print-row" type="button" data-id="<?= (int) $invoice['id'] ?>">Print invoice</button><?php if (! empty($invoice['order_id'])): ?><a class="dropdown-item" href="<?= base_url('patient/orders?order_id=' . (int) $invoice['order_id']) ?>">View linked order</a><?php endif; ?><?php if (! empty($invoice['prescription_id'])): ?><a class="dropdown-item" href="<?= base_url('patient/prescriptions?prescription_id=' . (int) $invoice['prescription_id']) ?>">View linked prescription</a><?php endif; ?></div></div></div></article><?php endforeach; ?></div><?php endif; ?>
